# KXM BLUEFIRE v22
# Windows PowerShell 5.1 + WinForms.
# ASCII-only source. UI text is stored in KXM_LANG_V22.json.
Set-StrictMode -Version 2.0
$ErrorActionPreference='SilentlyContinue'
Add-Type -AssemblyName System.Windows.Forms
Add-Type -AssemblyName System.Drawing

$Root=Join-Path $env:ProgramData 'KXM\BlueFire'
$BackupRoot=Join-Path $Root 'Backups'
$SessionRoot=Join-Path $Root 'Sessions'
$LogRoot=Join-Path $Root 'Logs'
$BaselinePointer=Join-Path $Root 'CURRENT_BASELINE.txt'
$SessionFile=Join-Path $SessionRoot 'ACTIVE_SESSION.xml'
$LogFile=Join-Path $LogRoot 'KXM.log'
$LangPath=Join-Path $PSScriptRoot 'KXM_LANG_V22.json'
New-Item -ItemType Directory -Path $BackupRoot -Force|Out-Null
New-Item -ItemType Directory -Path $SessionRoot -Force|Out-Null
New-Item -ItemType Directory -Path $LogRoot -Force|Out-Null
$TX=Get-Content -LiteralPath $LangPath -Raw -Encoding UTF8|ConvertFrom-Json
$Script:Lang='EN'

function T($key){$n=$key+'_'+$Script:Lang;$p=$TX.PSObject.Properties[$n];if($null -ne $p){return [string]$p.Value};$p=$TX.PSObject.Properties[$key+'_EN'];if($null -ne $p){return [string]$p.Value};return $key}
function Log($s){try{Add-Content -LiteralPath $LogFile -Value ('[{0}] {1}'-f (Get-Date -Format 'yyyy-MM-dd HH:mm:ss'),$s)-Encoding UTF8}catch{}}
function RegD($p,$n,$v){try{New-Item $p -Force|Out-Null;New-ItemProperty $p -Name $n -PropertyType DWord -Value $v -Force|Out-Null}catch{}}
function RegS($p,$n,$v){try{New-Item $p -Force|Out-Null;New-ItemProperty $p -Name $n -PropertyType String -Value $v -Force|Out-Null}catch{}}
function Snap($p,$n){$e=$false;$v=$null;$k='DWord';try{$i=Get-ItemProperty -LiteralPath $p -ErrorAction Stop;$x=$i.PSObject.Properties[$n];if($null -ne $x){$e=$true;$v=$x.Value;if($v -is [string]){$k='String'}}}catch{};return [pscustomobject]@{Path=$p;Name=$n;Exists=$e;Value=$v;Kind=$k}}
function RestoreSnap($e){if($e.Exists){if($e.Kind -eq 'String'){RegS $e.Path $e.Name ([string]$e.Value)}else{RegD $e.Path $e.Name ([int64]$e.Value)}}else{Remove-ItemProperty -LiteralPath $e.Path -Name $e.Name -ErrorAction SilentlyContinue}}
function DiskInfo{$h=$false;$s=$false;try{foreach($d in @(Get-PhysicalDisk -ErrorAction Stop)){$m=[string]$d.MediaType;if($m -match 'HDD'){$h=$true};if($m -match 'SSD'){$s=$true}}}catch{};if(-not $h -and -not $s){try{foreach($d in @(Get-CimInstance Win32_DiskDrive)){$m=([string]$d.Model+' '+[string]$d.MediaType+' '+[string]$d.InterfaceType);if($m -match 'SSD|Solid State|NVMe'){$s=$true}elseif($m -match 'HDD|Hard Disk|SATA|IDE'){$h=$true}}}catch{}};return [pscustomobject]@{HDD=$h;SSD=$s}}
function Hardware{$c=Get-CimInstance Win32_Processor|Select-Object -First 1;$cs=Get-CimInstance Win32_ComputerSystem;$g=@(Get-CimInstance Win32_VideoController);$d=DiskInfo;$ram=0;if($cs){$ram=[math]::Round($cs.TotalPhysicalMemory/1GB,1)};$gpu='Unknown';foreach($x in $g){if($gpu -eq 'Unknown'){$gpu=[string]$x.Name}else{$gpu+=' | '+[string]$x.Name}};$cpu='Unknown';$cores=0;$threads=0;$virt=$false;if($c){$cpu=[string]$c.Name;$cores=[int]$c.NumberOfCores;$threads=[int]$c.NumberOfLogicalProcessors;$virt=[bool]$c.VirtualizationFirmwareEnabled};return [pscustomobject]@{CPU=$cpu;Cores=$cores;Threads=$threads;RAM=$ram;GPU=$gpu;HDD=$d.HDD;SSD=$d.SSD;Virtualization=$virt}}
function Recommendation($h){$cores=4;$ram=4;if($h.Threads -lt 4){$cores=2};if($h.RAM -lt 8){$ram=2};$disk='HDD-safe';if($h.SSD){$disk='SSD-ready'};return [pscustomobject]@{Cores=$cores;RAM=$ram;Mode='High Performance';FPS='120 recommended / 240 ceiling optional';Disk=$disk}}
function BlueStacksPath{foreach($p in @("$env:ProgramFiles\BlueStacks_nxt\HD-Player.exe","$env:ProgramFiles\BlueStacks_nxt5\HD-Player.exe","${env:ProgramFiles(x86)}\BlueStacks_nxt\HD-Player.exe","${env:ProgramFiles(x86)}\BlueStacks_nxt5\HD-Player.exe")){if($p -and(Test-Path $p)){return $p}};return $null}
function CpuLoad{try{$c=Get-CimInstance Win32_Processor|Measure-Object -Property LoadPercentage -Average;return [math]::Round($c.Average,0)}catch{return 0}}
function MemUsed{try{$os=Get-CimInstance Win32_OperatingSystem;$total=[math]::Round($os.TotalVisibleMemorySize/1MB,1);$free=[math]::Round($os.FreePhysicalMemory/1MB,1);return [math]::Round($total-$free,1)}catch{return 0}}

function EnsureBaseline{if(Test-Path $BaselinePointer){$old=(Get-Content $BaselinePointer -Raw -Encoding UTF8).Trim();if($old -and(Test-Path(Join-Path $old 'Baseline.xml'))){return}};$d=Join-Path $BackupRoot(Get-Date -Format 'yyyyMMdd_HHmmss');New-Item -ItemType Directory $d -Force|Out-Null;$st=[ordered]@{Created=(Get-Date).ToString('o');Power=((powercfg /getactivescheme)-join ' ');Registry=New-Object System.Collections.ArrayList;Services=New-Object System.Collections.ArrayList};foreach($x in @(@('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile','SystemResponsiveness'),@('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile','NetworkThrottlingIndex'),@('HKLM:\SYSTEM\CurrentControlSet\Control\PriorityControl','Win32PrioritySeparation'),@('HKLM:\SYSTEM\CurrentControlSet\Control\Power\PowerThrottling','PowerThrottlingOff'),@('HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers','HwSchMode'),@('HKLM:\SOFTWARE\Microsoft\Windows\Dwm','OverlayTestMode'),@('HKCU:\Software\Microsoft\GameBar','AutoGameModeEnabled'),@('HKCU:\System\GameConfigStore','GameDVR_Enabled'))){$st.Registry.Add((Snap $x[0] $x[1]))};try{$svc=Get-CimInstance Win32_Service -Filter "Name='SysMain'";$st.Services.Add([pscustomobject]@{Name='SysMain';Start=[string]$svc.StartMode;State=[string]$svc.State})}catch{};$st|Export-Clixml(Join-Path $d 'Baseline.xml');powercfg /list|Out-File(Join-Path $d 'PowerPlans.txt')-Encoding UTF8;bcdedit /enum all|Out-File(Join-Path $d 'BCD.txt')-Encoding UTF8;Set-Content $BaselinePointer $d -Encoding UTF8;Log('Baseline created: '+$d)}

function RestoreBaseline{$d=$null;if(Test-Path $BaselinePointer){$d=(Get-Content $BaselinePointer -Raw -Encoding UTF8).Trim()};if(-not $d -or -not(Test-Path(Join-Path $d 'Baseline.xml'))){[System.Windows.Forms.MessageBox]::Show((T 'NoBase'),'KXM // Restore')|Out-Null;return};$a=[System.Windows.Forms.MessageBox]::Show((T 'RestoreQ'),'KXM // Restore',[System.Windows.Forms.MessageBoxButtons]::YesNo,[System.Windows.Forms.MessageBoxIcon]::Warning);if($a -ne [System.Windows.Forms.DialogResult]::Yes){return};$st=Import-Clixml(Join-Path $d 'Baseline.xml');foreach($e in $st.Registry){RestoreSnap $e};foreach($s in $st.Services){if($s.Start -eq 'Auto'){Set-Service $s.Name -StartupType Automatic}elseif($s.Start -eq 'Manual'){Set-Service $s.Name -StartupType Manual}elseif($s.Start -eq 'Disabled'){Set-Service $s.Name -StartupType Disabled};if($s.State -eq 'Running'){Start-Service $s.Name}elseif($s.State -eq 'Stopped'){Stop-Service $s.Name -Force}};if($st.Power-match'([0-9a-fA-F-]{36})'){powercfg /setactive $Matches[1]|Out-Null};Log('Baseline restored');[System.Windows.Forms.MessageBox]::Show((T 'Restored'),'KXM // Restore')|Out-Null}

function GameReady{$session=[ordered]@{Started=(Get-Date).ToString('o');Power=((powercfg /getactivescheme)-join ' ');BlueStacksPriority=$null};if(Test-Path $SessionFile){return 'Session already active.'};$p=Get-Process -Name 'HD-Player' -ErrorAction SilentlyContinue|Select-Object -First 1;if($p){$session.BlueStacksPriority=[int]$p.PriorityClass};$session|Export-Clixml $SessionFile;EnsureBaseline;foreach($d in @($env:TEMP,(Join-Path $env:LOCALAPPDATA 'Temp'),'C:\Windows\Temp')){if(Test-Path $d){Remove-Item -LiteralPath(Join-Path $d '*')-Recurse -Force -ErrorAction SilentlyContinue}};ipconfig /flushdns|Out-Null;powercfg /setactive SCHEME_MIN|Out-Null;if($p){try{$p.PriorityClass='AboveNormal'}catch{}};Log('GAME READY start');return 'GAME READY ACTIVE.`r`nTemp cleanup complete.`r`nDNS flushed.`r`nHigh Performance active.'}
function EndGameSession{if(-not(Test-Path $SessionFile)){return 'No active KXM gaming session.'};$s=Import-Clixml $SessionFile;if($s.Power-match'([0-9a-fA-F-]{36})'){powercfg /setactive $Matches[1]|Out-Null};Remove-Item $SessionFile -Force -ErrorAction SilentlyContinue;Log('GAME SESSION ended');return 'Gaming session ended.`r`nOriginal power plan restored.'}

function SmartOptimize{EnsureBaseline;$h=Hardware;powercfg /setactive SCHEME_MIN|Out-Null;RegD 'HKCU:\Software\Microsoft\GameBar' 'AutoGameModeEnabled' 1;RegD 'HKCU:\System\GameConfigStore' 'GameDVR_Enabled' 0;RegD 'HKCU:\Software\Microsoft\Windows\CurrentVersion\GameDVR' 'AppCaptureEnabled' 0;$mm='HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile';$g="$mm\Tasks\Games";RegD $mm 'SystemResponsiveness' 0;RegD $mm 'NetworkThrottlingIndex' 4294967295;RegD $g 'GPU Priority' 8;RegD $g 'Priority' 6;RegD 'HKLM:\SYSTEM\CurrentControlSet\Control\PriorityControl' 'Win32PrioritySeparation' 38;RegD 'HKLM:\SYSTEM\CurrentControlSet\Control\Power\PowerThrottling' 'PowerThrottlingOff' 1;$bs=BlueStacksPath;if($bs){RegS 'HKCU:\Software\Microsoft\DirectX\UserGpuPreferences' $bs 'GpuPreference=2;'};if($h.HDD -or $h.RAM -le 8){Set-Service SysMain -StartupType Automatic;Start-Service SysMain};Log('SMART OPTIMIZE');return $h}
function NetOptimize{EnsureBaseline;netsh int tcp set global rss=enabled|Out-Null;netsh int tcp set global autotuninglevel=normal|Out-Null;Log('NETWORK optimize')}

