$i=0
foreach($name in $btnNames){$b=New-Object System.Windows.Forms.Button;$b.Text=$name;$col=$i%5;$row=[math]::Floor($i/5);$b.Location=New-Object System.Drawing.Point((18+150*$col),(35+92*$row));$b.Size=New-Object System.Drawing.Size(138,65);$b.BackColor=[System.Drawing.Color]::FromArgb(27,34,44);$b.ForeColor=[System.Drawing.Color]::White;$b.FlatStyle='Flat';$b.Tag=$name;$b.Add_Click({$n=$this.Tag;$hh=Hardware;$rr=Recommendation $hh;if($n -eq 'Hardware Audit'){$details.Text=("HARDWARE AUDIT`r`n`r`nCPU: {0}`r`nCores/Threads: {1}/{2}`r`nRAM: {3} GB`r`nGPU: {4}`r`nHDD: {5}`r`nSSD: {6}`r`nVirtualization: {7}"-f $hh.CPU,$hh.Cores,$hh.Threads,$hh.RAM,$hh.GPU,$hh.HDD,$hh.SSD,$hh.Virtualization)}elseif($n -eq 'Game Profiles'){$details.Text='FREE FIRE PROFILE`r`n`r`nBlueStacks CPU: 4 cores`r`nBlueStacks RAM: 4 GB`r`nMode: High Performance`r`nFPS: 120 recommended / 240 ceiling optional`r`n`r`nFree Fire MAX uses the same base profile.'}elseif($n -eq 'Conflict Check'){$conf=@();if(Get-Process -Name 'Discord' -ErrorAction SilentlyContinue){$conf+='Discord running'};if(Get-Service 'vmms' -ErrorAction SilentlyContinue){if((Get-Service 'vmms').Status -eq 'Running'){$conf+='Hyper-V service running'}};if(Get-Process -Name 'RivaTunerStatisticsServer' -ErrorAction SilentlyContinue){$conf+='RTSS running'};if(Get-Service 'com.docker.service' -ErrorAction SilentlyContinue){if((Get-Service 'com.docker.service').Status -eq 'Running'){$conf+='Docker running'}};if($conf.Count -eq 0){$details.Text='CONFLICT CHECK`r`n`r`nNo common conflicts detected.'}else{$details.Text='CONFLICT CHECK`r`n`r`n'+($conf -join "`r`n")}}elseif($n -eq 'Benchmark'){$file=Join-Path $Root('benchmark_'+(Get-Date -Format 'yyyyMMdd_HHmmss')+'.txt');@('KXM BLUEFIRE v22',"$(Get-Date)","CPU: $($hh.CPU)","RAM: $($hh.RAM) GB","GPU: $($hh.GPU)","CPU Load: $(CpuLoad)%","Memory Used: $(MemUsed) GB","Power: $((powercfg /getactivescheme)-join ' ')")|Set-Content $file -Encoding UTF8;$details.Text='BENCHMARK SNAPSHOT SAVED`r`n`r`n'+$file}else{$details.Text=($n+'`r`n`r`nFeature ready. Use the Quick Play actions for changes.')}});$tools.Controls.Add($b);$i++}

